fn solveCubic(p: f32, q: f32, offset: f32) -> vec3f {
    let p3 = select(p * p * p, 0.0001, p == 0.0);
    let d  = q * q + p3 * 0.148148; // Discriminant: q^2 + (4/27) p^3

    if (d >= 0.0) {
        let z = sqrt(d);
        let x = (vec2f(z, -z) - q) * 0.5;
        let uv = sign(x) * pow(abs(x), vec2f(0.3333333));
        return vec3f(offset + uv.x + uv.y);
    }

    let v = acos(-sqrt(-27.0 / p3) * q * 0.5) * 0.3333333;
    let m = cos(v);
    let n = sin(v) * 1.732050808; // sqrt(3.0)
    return vec3<f32>(m + m, -n - m, n - m) * sqrt(-p * 0.3333333) + offset;
}
